]$official_profiles$::jsonb) AS s(name text, details jsonb);

DO $validate$
BEGIN
  IF (SELECT count(*) FROM pg_temp.cse_official_profiles) <> 252 OR EXISTS (
    SELECT 1 FROM pg_temp.cse_official_profiles s
    LEFT JOIN public.faculty f ON f.department = 'CSE'
      AND lower(btrim(regexp_replace(f.name, '[[:space:]]+', ' ', 'g')))
        = lower(btrim(regexp_replace(s.name, '[[:space:]]+', ' ', 'g')))
    GROUP BY lower(btrim(regexp_replace(s.name, '[[:space:]]+', ' ', 'g')))
    HAVING count(f.id) <> 1 OR count(*) <> 1
  ) THEN
    RAISE EXCEPTION 'STOP: expected exactly one existing CSE faculty row for every source identity';
  END IF;
END;
$validate$;

UPDATE public.faculty f
SET official_profile = s.details
FROM pg_temp.cse_official_profiles s
WHERE f.department = 'CSE'
  AND lower(btrim(regexp_replace(f.name, '[[:space:]]+', ' ', 'g')))
    = lower(btrim(regexp_replace(s.name, '[[:space:]]+', ' ', 'g')))
  AND f.official_profile IS DISTINCT FROM s.details;

CREATE OR REPLACE VIEW public.faculty_public
WITH (security_barrier = true, security_invoker = false) AS
SELECT id, slug, name, initials, department, summary_note, created_at,
  CASE WHEN department = 'CSE' AND official_profile IS NOT NULL THEN
    jsonb_strip_nulls(jsonb_build_object(
      'designation', official_profile->'designation',
      'email', CASE WHEN official_profile->>'email' ~* '^[a-z0-9._+-]+@bracu[.]ac[.]bd$'
                    THEN official_profile->'email' END,
      'address', official_profile->'address',
      'roles', official_profile->'roles',
      'levels', official_profile->'levels',
      'types', official_profile->'types',
      'research_interests', official_profile->'research_interests'
    ))
  END AS official_profile
FROM public.faculty
WHERE is_active;

COMMIT;
